import { fileURLToPath } from 'node:url'

import { defineConfig } from 'vitest/config'

export default defineConfig({
  resolve: {
    alias: {
      // The real `#app` is generated by Nuxt for the app being built. Pointing
      // it at a stub is what lets these tests exercise the actual plugin file -
      // the one that ships - rather than a copy of its body.
      '#app': fileURLToPath(new URL('./tests/stubs/nuxt-app.ts', import.meta.url)),
    },
  },
  test: {
    // The plugin is installed into a real Vue app and components are mounted
    // against it, so it needs a document.
    environment: 'happy-dom',
  },
})
